function(container, tables) {
    // 業務ロジックモジュールをインポート
    const {
        collectSalesData,
        classifySalesDataByProduct,
        classifySalesDataByStore,
        filterValidProductData,
        collectWeatherData,
        collectEventData,
        collectSeasonalData,
        analyzeCorrelationSalesWeather,
        analyzeCorrelationSalesEvent,
        analyzeCorrelationSalesSeason,
        compareWithHistoricalData,
        findAlternativeComparisonData,
        validateComparisonPeriod
    } = window.businessLogic || {};

    // 予測精度監視に必要な要素を取得
    const refreshBtn = container.querySelector('#refresh-accuracy-btn');
    const productSelect = container.querySelector('#product-select');
    const storeSelect = container.querySelector('#store-select');
    const periodSelect = container.querySelector('#period-select');
    const accuracyTable = container.querySelector('#accuracy-table tbody');
    const accuracyChart = container.querySelector('#accuracy-chart');
    const alertsContainer = container.querySelector('#accuracy-alerts');

    // 商品・店舗選択肢を初期化
    function initializeSelectors() {
        // 商品データを取得して選択肢に設定
        window.aivicApi.list('products').then(products => {
            productSelect.innerHTML = '<option value="">全商品</option>';
            products.forEach(product => {
                const option = document.createElement('option');
                option.value = product.id;
                option.textContent = product.name;
                productSelect.appendChild(option);
            });
        }).catch(error => {
            window.aivicNotify.error('商品データの取得に失敗しました');
        });

        // 店舗データを取得して選択肢に設定
        window.aivicApi.list('stores').then(stores => {
            storeSelect.innerHTML = '<option value="">全店舗</option>';
            stores.forEach(store => {
                const option = document.createElement('option');
                option.value = store.id;
                option.textContent = store.name;
                storeSelect.appendChild(option);
            });
        }).catch(error => {
            window.aivicNotify.error('店舗データの取得に失敗しました');
        });
    }

    // 予測精度を計算して表示
    async function calculateAndDisplayAccuracy() {
        try {
            const productId = productSelect.value;
            const storeId = storeSelect.value;
            const period = periodSelect.value;

            // 比較期間の妥当性をチェック
            if (!validateComparisonPeriod(period)) {
                window.aivicNotify.error('選択された期間は比較に適していません');
                return;
            }

            // 売上データを収集
            const salesData = await collectSalesData(productId, storeId, period);

            if (!salesData || salesData.length === 0) {
                window.aivicNotify.error('指定条件での売上データが見つかりません');
                return;
            }

            // 有効な商品データをフィルタリング
            const validData = filterValidProductData(salesData);

            // 予測データを取得
            const predictions = await window.aivicApi.list('predictions', {
                productId: productId,
                storeId: storeId,
                period: period
            });

            // 実績と予測を比較して精度を計算
            const accuracyResults = compareWithHistoricalData(validData, predictions);

            // 結果をテーブルに表示
            displayAccuracyTable(accuracyResults);

            // チャートを更新
            updateAccuracyChart(accuracyResults);

            // アラートをチェック
            checkAccuracyAlerts(accuracyResults);

            window.aivicNotify.success('予測精度の更新が完了しました');

        } catch (error) {
            console.error('予測精度計算エラー:', error);
            window.aivicNotify.error('予測精度の計算に失敗しました');
        }
    }

    // 精度結果をテーブルに表示
    function displayAccuracyTable(results) {
        if (!accuracyTable) return;

        accuracyTable.innerHTML = '';

        results.forEach(result => {
            const row = document.createElement('tr');
            row.innerHTML = `
                <td>${result.productName || '全商品'}</td>
                <td>${result.storeName || '全店舗'}</td>
                <td>${result.period}</td>
                <td>${(result.accuracy * 100).toFixed(2)}%</td>
                <td>${result.mae.toFixed(2)}</td>
                <td>${result.rmse.toFixed(2)}</td>
                <td>
                    <span class="accuracy-status ${result.status}">
                        ${result.status === 'good' ? '良好' : result.status === 'warning' ? '注意' : '要改善'}
                    </span>
                </td>
            `;
            accuracyTable.appendChild(row);
        });
    }

    // 精度チャートを更新
    function updateAccuracyChart(results) {
        if (!accuracyChart) return;

        const chartData = results.map(result => ({
            label: `${result.productName || '全商品'} - ${result.storeName || '全店舗'}`,
            accuracy: result.accuracy * 100,
            mae: result.mae,
            rmse: result.rmse
        }));

        // 簡易チャート表示（実際のプロジェクトではChart.js等を使用）
        accuracyChart.innerHTML = '';
        chartData.forEach(data => {
            const bar = document.createElement('div');
            bar.className = 'accuracy-bar';
            bar.style.width = `${data.accuracy}%`;
            bar.style.height = '20px';
            bar.style.backgroundColor = data.accuracy >= 80 ? '#28a745' : data.accuracy >= 60 ? '#ffc107' : '#dc3545';
            bar.style.margin = '5px 0';
            bar.title = `${data.label}: ${data.accuracy.toFixed(2)}%`;

            const label = document.createElement('div');
            label.textContent = `${data.label}: ${data.accuracy.toFixed(2)}%`;
            label.style.fontSize = '12px';

            accuracyChart.appendChild(label);
            accuracyChart.appendChild(bar);
        });
    }

    // 精度アラートをチェック
    function checkAccuracyAlerts(results) {
        if (!alertsContainer) return;

        alertsContainer.innerHTML = '';

        const lowAccuracyItems = results.filter(result => result.accuracy < 0.6);
        const highErrorItems = results.filter(result => result.mae > 100 || result.rmse > 150);

        if (lowAccuracyItems.length > 0) {
            const alert = document.createElement('div');
            alert.className = 'alert alert-danger';
            alert.innerHTML = `
                <strong>精度低下アラート:</strong> 
                ${lowAccuracyItems.length}件の商品で予測精度が60%を下回っています。
                モデルの再学習を検討してください。
            `;
            alertsContainer.appendChild(alert);
        }

        if (highErrorItems.length > 0) {
            const alert = document.createElement('div');
            alert.className = 'alert alert-warning';
            alert.innerHTML = `
                <strong>誤差増大アラート:</strong> 
                ${highErrorItems.length}件の商品で予測誤差が基準値を超えています。
                パラメータの調整が必要です。
            `;
            alertsContainer.appendChild(alert);
        }

        if (lowAccuracyItems.length === 0 && highErrorItems.length === 0) {
            const alert = document.createElement('div');
            alert.className = 'alert alert-success';
            alert.innerHTML = '<strong>正常:</strong> すべての予測精度が基準値内です。';
            alertsContainer.appendChild(alert);
        }
    }

    // イベントハンドラーを設定
    if (refreshBtn) {
        refreshBtn.addEventListener('click', calculateAndDisplayAccuracy);
    }

    // 選択肢変更時の自動更新
    [productSelect, storeSelect, periodSelect].forEach(select => {
        if (select) {
            select.addEventListener('change', calculateAndDisplayAccuracy);
        }
    });

    // 初期化実行
    initializeSelectors();

    // 初期データ読み込み
    setTimeout(() => {
        calculateAndDisplayAccuracy();
    }, 500);
}
